import{_ as t,o as a,c as o,a3 as n}from"./chunks/framework.ByIHJIQ1.js";const h=JSON.parse('{"title":"1. Introduction to Graph Reduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/01_introduction.md","filePath":"guide/01_introduction.md"}'),r={name:"guide/01_introduction.md"};function i(s,e,c,d,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="_1-introduction-to-graph-reduction" tabindex="-1">1. Introduction to Graph Reduction <a class="header-anchor" href="#_1-introduction-to-graph-reduction" aria-label="Permalink to &quot;1. Introduction to Graph Reduction&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">Paper Insight</p><p>Based on Section 1 &amp; 2 of the IFL research paper (<em>&quot;A Portable VM-based implementation Platform for non-strict Functional Programming Languages&quot;</em>).</p></div><p>Dit is een regel om te bekijken of het wel goed gaat!!!!</p><p>Functional programming languages treat computation as the mathematical evaluation of expressions. In a <strong>lazy (non-strict)</strong> language:</p><ul><li>Expressions are not evaluated when passed as arguments.</li><li>Instead, they are suspended as <strong>Thunks</strong> (graph nodes) on the heap.</li><li>An expression is reduced to <strong>Weak Head Normal Form (WHNF)</strong> only when its value is demanded.</li></ul><hr><h2 id="the-core-concept" tabindex="-1">The Core Concept <a class="header-anchor" href="#the-core-concept" aria-label="Permalink to &quot;The Core Concept&quot;">​</a></h2><p>Unlike stack-based imperative languages that push primitive values directly, a lazy virtual machine manages an <strong>expression graph</strong> that is rewritten step-by-step (<em>graph reduction</em>).</p>',8)])])}const m=t(r,[["render",i]]);export{h as __pageData,m as default};
